package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class ProjectEvidenceActivity extends Activity{private SharedPreferences p;private EditText total,standardized,newData,sharing,partners,activities,issues,expenses,variance,tech,sustain;@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("evidence",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Preuves et reddition de comptes",27,true));total=f(r,"Nombre total de données / fiches","total");standardized=f(r,"Nombre de données adaptées / standardisées","standardized");newData=f(r,"Nouvelles données standardisées ajoutées","newData");sharing=f(r,"Modalités de partage / accès / données ouvertes","sharing");partners=f(r,"Partenaires et réutilisations","partners");activities=f(r,"Activités réalisées","activities");issues=f(r,"Problèmes rencontrés et correctifs","issues");expenses=f(r,"Dépenses réelles","expenses");variance=f(r,"Écarts au budget / calendrier","variance");tech=f(r,"Approche technologique et interopérabilité","tech");sustain=f(r,"Développement durable / pérennité","sustain");Button save=Ui.primary(this,"Enregistrer les preuves");save.setOnClickListener(v->save());r.addView(save);Button share=Ui.secondary(this,"Partager le rapport de suivi");share.setOnClickListener(v->{save();double t=num(total),s=num(standardized);double pct=t>0?s*100/t:0;String report="Culture du Québec — Suivi de standardisation\nTotal : "+total.getText()+"\nStandardisées : "+standardized.getText()+"\nPourcentage : "+String.format(java.util.Locale.CANADA_FRENCH,"%.1f %%",pct)+"\nNouvelles : "+newData.getText()+"\nPartage : "+sharing.getText()+"\nPartenaires : "+partners.getText()+"\nActivités : "+activities.getText()+"\nProblèmes : "+issues.getText()+"\nDépenses : "+expenses.getText()+"\nÉcarts : "+variance.getText()+"\nTechnologie : "+tech.getText()+"\nPérennité : "+sustain.getText();Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,report);startActivity(Intent.createChooser(i,"Partager"));});r.addView(share);setContentView(Ui.wrap(this,r));}private EditText f(LinearLayout r,String h,String k){EditText e=Ui.field(this,h,p.getString(k,""));r.addView(e);return e;}private void save(){p.edit().putString("total",total.getText().toString()).putString("standardized",standardized.getText().toString()).putString("newData",newData.getText().toString()).putString("sharing",sharing.getText().toString()).putString("partners",partners.getText().toString()).putString("activities",activities.getText().toString()).putString("issues",issues.getText().toString()).putString("expenses",expenses.getText().toString()).putString("variance",variance.getText().toString()).putString("tech",tech.getText().toString()).putString("sustain",sustain.getText().toString()).apply();Toast.makeText(this,"Preuves enregistrées",Toast.LENGTH_SHORT).show();}private double num(EditText e){try{return Double.parseDouble(e.getText().toString().replace(',','.'));}catch(Exception x){return 0;}}}
